"""Parse a Mintlify documentation site into a structured page index.

Walks every .mdx page the site publishes, extracts frontmatter and content, and
builds a DocIndex that maps each page to its URL, title, and cleaned markdown
body. Mintlify publishes every .mdx file except snippets and paths listed in
`.mintignore`, so the same rules apply to the Rasa docs repo and to the in-repo
Mantle docs; only the per-site settings in ``MintlifySite`` differ.
"""

import fnmatch
import hashlib
import re
import subprocess
from pathlib import Path
from typing import Dict, List, Optional

import structlog
from pydantic import BaseModel, ConfigDict, Field

from rasa.builder.document_retrieval.source import ContentType, SourceDocument

structlogger = structlog.get_logger()

MINTIGNORE_FILENAME = ".mintignore"
MINTLIFY_CONFIG_FILENAME = "docs.json"
MINTLIFY_SNIPPETS_DIR = "snippets"

_INDEX_DOC_ID = "index"


class MintlifySite(BaseModel):
    """Per-site settings for a Mintlify docs site.

    Everything else about parsing a site (which pages are published, how URLs
    map to files) follows Mintlify's own rules and is shared by all sites.
    """

    model_config = ConfigDict(frozen=True)

    source: str = Field(
        description="Corpus name stamped on every document, e.g. 'rasa-docs'."
    )
    base_url: str = Field(description="URL the site's root page is served from.")
    default_topic: str = Field(
        description="Topic for pages whose first path segment is not in "
        "topic_by_prefix."
    )
    topic_by_prefix: Dict[str, str] = Field(
        default_factory=dict,
        description="Coarse topic keyed by a doc_id's first path segment.",
    )

    def url_for(self, doc_id: str) -> str:
        """Return the canonical URL of the page with ``doc_id``."""
        base_url = self.base_url.rstrip("/")
        if doc_id == _INDEX_DOC_ID:
            return base_url
        return f"{base_url}/{doc_id}"

    def topic_for(self, doc_id: str) -> str:
        """Return the coarse topic of the page with ``doc_id``."""
        first_segment = doc_id.split("/", 1)[0]
        return self.topic_by_prefix.get(first_segment, self.default_topic)


# The topic lives with the docs producer: the retrieval pipeline stays agnostic
# and just carries it as metadata (e.g. for ``LocalRetrievalConfig.topic_filter``).
RASA_DOCS_SITE = MintlifySite(
    source="rasa-docs",
    base_url="https://rasa.com/docs",
    default_topic="framework",
    topic_by_prefix={"studio": "studio"},
)
MANTLE_DOCS_SITE = MintlifySite(
    source="mantle-docs",
    # Copy of rasa.cli.tools.constants.DEFAULT_MANTLE_LLMS_TXT_BASE_URL: that
    # module loads prompt_toolkit, so it isn't imported here. Keep in sync.
    base_url="https://rasa-2f7eb63d.mintlify.site",
    default_topic="mantle",
)
# Every known site, keyed by its corpus name (``MintlifySite.source``).
MINTLIFY_SITES: Dict[str, MintlifySite] = {
    site.source: site for site in (RASA_DOCS_SITE, MANTLE_DOCS_SITE)
}


def _content_version(content: str) -> str:
    """Return a short content hash used as a document's sync version.

    Lets incremental sync detect which pages actually changed between corpus
    snapshots.
    """
    return hashlib.sha1(content.encode("utf-8"), usedforsecurity=False).hexdigest()[:16]


class DocPage(BaseModel):
    """A single documentation page."""

    doc_id: str = Field(
        description="Page path without extension, e.g. 'pro/build/writing-flows'"
    )
    url: str = Field(description="Full canonical URL on the docs site")
    title: str = Field(description="Page title from frontmatter or filename")
    content: str = Field(description="Cleaned markdown body (no frontmatter, no JSX)")

    def to_source_document(self, site: MintlifySite) -> SourceDocument:
        """Adapt this page into the canonical ingestion DTO.

        Args:
            site: The site this page was parsed from; supplies source and topic.
        """
        return SourceDocument(
            id=self.doc_id,
            title=self.title,
            content=self.content,
            source=site.source,
            content_type=ContentType.MARKDOWN,
            url=self.url,
            version=_content_version(self.content),
            metadata={"topic": site.topic_for(self.doc_id)},
        )


class DocIndex(BaseModel):
    """Index of all documentation pages in the repo."""

    pages: list[DocPage]
    docs_repo_commit: str = Field(description="Git SHA of the docs repo at index time")


def _get_git_commit(repo_path: Path) -> str:
    """Get the current HEAD commit SHA of the repo."""
    try:
        result = subprocess.run(
            ["git", "rev-parse", "HEAD"],
            cwd=repo_path,
            capture_output=True,
            text=True,
            check=True,
        )
        return result.stdout.strip()
    except (subprocess.CalledProcessError, FileNotFoundError):
        structlogger.warning("docs_index.git_commit_failed", repo_path=str(repo_path))
        return "unknown"


def _parse_frontmatter(raw: str) -> tuple[dict[str, str], str]:
    """Split frontmatter from markdown body.

    Returns (frontmatter_dict, body). If no frontmatter is found,
    returns an empty dict and the full content as body.
    """
    match = re.match(r"^---\s*\n(.*?)\n---\s*\n", raw, re.DOTALL)
    if not match:
        return {}, raw

    fm_block = match.group(1)
    body = raw[match.end() :]

    # Simple key: value parsing (handles single-line values only,
    # which covers title — the field we need)
    fm: dict[str, str] = {}
    for line in fm_block.splitlines():
        if ":" in line and not line.startswith(" ") and not line.startswith("\t"):
            key, _, value = line.partition(":")
            key = key.strip()
            value = value.strip().strip("\"'")
            if key and value:
                fm[key] = value

    return fm, body


def _clean_markdown(body: str) -> str:
    """Strip JSX imports, components, and MDX-specific syntax."""
    lines = body.splitlines()
    cleaned: list[str] = []

    for line in lines:
        # Skip import statements
        if re.match(r"^\s*import\s+", line):
            continue
        # Skip JSX self-closing tags like <Component ... />
        if re.match(r"^\s*<\w+[^>]*/>\s*$", line):
            continue
        cleaned.append(line)

    text = "\n".join(cleaned)

    # Remove inline JSX tags (opening and closing), keep inner content
    text = re.sub(r"<(\w+)[^>]*>", "", text)
    text = re.sub(r"</\w+>", "", text)

    # Collapse excessive blank lines
    text = re.sub(r"\n{3,}", "\n\n", text)

    return text.strip()


def _load_mintignore_patterns(docs_root: Path) -> tuple[str, ...]:
    """Return ignore patterns from the site's `.mintignore`, if present."""
    mintignore_path = docs_root / MINTIGNORE_FILENAME
    if not mintignore_path.is_file():
        return ()

    patterns: list[str] = []
    for line in mintignore_path.read_text(encoding="utf-8").splitlines():
        pattern = line.strip()
        if not pattern or pattern.startswith("#"):
            continue
        patterns.append(pattern)
    return tuple(patterns)


def _matches_mintignore_pattern(relative_posix: str, pattern: str) -> bool:
    """Test whether a site-relative path matches one `.mintignore` pattern."""
    if pattern.endswith("/**"):
        prefix = pattern[:-3]
        return relative_posix == prefix or relative_posix.startswith(f"{prefix}/")
    return fnmatch.fnmatch(relative_posix, pattern)


def _is_mintignored(relative_path: Path, patterns: tuple[str, ...]) -> bool:
    """Test whether a docs path is unpublished according to `.mintignore`."""
    relative_posix = relative_path.as_posix()
    return any(
        _matches_mintignore_pattern(relative_posix, pattern) for pattern in patterns
    )


def _published_pages(docs_root: Path) -> List[Path]:
    """Return the site-relative paths of every .mdx page Mintlify publishes.

    Mintlify serves every .mdx file except reusable snippets and paths listed
    in `.mintignore`, including pages that are absent from the navigation.
    """
    patterns = _load_mintignore_patterns(docs_root)
    relative_paths = (path.relative_to(docs_root) for path in docs_root.rglob("*.mdx"))
    return sorted(
        relative_path
        for relative_path in relative_paths
        if relative_path.parts[0] != MINTLIFY_SNIPPETS_DIR
        and not _is_mintignored(relative_path, patterns)
    )


def _read_page(
    docs_root: Path, relative_path: Path, site: MintlifySite
) -> Optional[DocPage]:
    """Parse one published .mdx page.

    The doc_id is the page path without extension, which is also the path
    Mintlify serves it at.

    Returns:
        The parsed page, or ``None`` when nothing is left after cleaning
        (logged as a warning so empty pages stay visible).
    """
    raw = (docs_root / relative_path).read_text(encoding="utf-8")
    frontmatter, body = _parse_frontmatter(raw)
    content = _clean_markdown(body)
    if not content:
        structlogger.warning("docs_index.empty_page", path=str(relative_path))
        return None

    doc_id = relative_path.with_suffix("").as_posix()
    return DocPage(
        doc_id=doc_id,
        url=site.url_for(doc_id),
        title=frontmatter.get("title") or relative_path.stem,
        content=content,
    )


def build_index(docs_root: Path, site: MintlifySite = RASA_DOCS_SITE) -> DocIndex:
    """Build a DocIndex by parsing every published .mdx page of a Mintlify site.

    Args:
        docs_root: Root of the Mintlify site, the directory holding `docs.json`.
        site: Per-site settings used to build page URLs.

    Returns:
        DocIndex with all parsed pages, stamped with the HEAD commit of the git
        checkout containing ``docs_root``.

    Raises:
        FileNotFoundError: If ``docs_root`` is not a Mintlify site root.
    """
    if not (docs_root / MINTLIFY_CONFIG_FILENAME).is_file():
        raise FileNotFoundError(
            f"Mintlify docs root not found: {docs_root} has no "
            f"{MINTLIFY_CONFIG_FILENAME}."
        )

    pages = [
        page
        for relative_path in _published_pages(docs_root)
        if (page := _read_page(docs_root, relative_path, site)) is not None
    ]
    commit = _get_git_commit(docs_root)

    structlogger.info(
        "docs_index.built",
        source=site.source,
        page_count=len(pages),
        docs_repo_commit=commit,
    )

    return DocIndex(pages=pages, docs_repo_commit=commit)
